def build_group(group_name: str):
    all_elems = list(itertools.permutations(range(N)))
    if group_name == 'A5':
        elems = [p for p in all_elems if permutation_parity(p) == 0]
    elif group_name == 'S5':
        elems = all_elems
    else:
        raise ValueError(f'unknown group={group_name!r}; use A5 or S5')
    index = {p: i for i, p in enumerate(elems)}
    table = torch.empty((len(elems), len(elems)), dtype=torch.long)
    for i, a in enumerate(elems):
        for j, b in enumerate(elems):
            comp = tuple(b[a[k]] for k in range(N))
            table[i, j] = index[comp]
    identity = index[tuple(range(N))]
    return elems, table, identity

