def encode_batch(sym: torch.Tensor, device: torch.device):
    toks = ALPHABET[sym]
    batch, seq_len = sym.shape
    targets = torch.empty((batch, seq_len), dtype=torch.long)
    cur = torch.full((batch,), IDENTITY_IDX, dtype=torch.long)
    for t in range(seq_len):
        cur = MULT_TABLE_CPU[cur, toks[:, t]]
        targets[:, t] = cur
    x = encode_symbols(sym, toks)
    return x.to(device, non_blocking=True), targets.to(device, non_blocking=True)

