def eval_batch_size(model_name, L):
    base = int(CFG['batch_size'])
    if model_name.startswith('transformer_rope') and L >= 2048:
        return 1
    if L >= 4096:
        return min(base, 4)
    if L >= 2048:
        return min(base, 8)
    if L >= 1024:
        return min(base, 12)
    return base

