make_train_batch.text:
def make_train_batch(step: int, batch: int, seq_len: int, device: torch.device):
    # Length curriculum: early steps expose only the SHORTEST words so the model learns
    # the group action (state o input -> state) with clean, shallow credit assignment;
    # progressively longer words are unlocked for retention / length generalization.
    # Training straight at long lengths never bootstraps (the earlier chance-flat bug).
    # Sampling stays on the small cached set of shapes so kernel/cuDNN autotune is not
    # re-triggered every step.
    if CURRICULUM_STEPS > 0:
        frac = min(1.0, step / CURRICULUM_STEPS)
        n_allowed = max(1, math.ceil(frac * len(TRAIN_LENGTHS)))
    else:
        n_allowed = len(TRAIN_LENGTHS)
    L = TRAIN_LENGTHS[int(torch.randint(0, n_allowed, (1,)).item())]
    return make_batch(batch, L, device)

