def probe_acc(model, model_name, L, device):
    was_training = model.training
    model.eval()
    try:
        x, y = make_batch(min(int(CFG['batch_size']), 8), int(L), device)
        _, acc = loss_acc(model.forward_sequence(x), y)
    finally:
        if was_training:
            model.train()
    return acc

