def scheduled_lr(step: int, base_lr: float, warmup: int, total: int) -> float:
    # Linear warmup, then (if lr_schedule=='cosine') cosine decay from base_lr down to
    # lr_min_frac*base_lr over the nominal `total` steps. Constant after warmup otherwise.
    if warmup > 0 and step <= warmup:
        return base_lr * step / warmup
    if CFG.get('lr_schedule', 'constant') != 'cosine' or total <= warmup:
        return base_lr
    min_frac = float(CFG.get('lr_min_frac', 0.0))
    prog = min(1.0, max(0.0, (step - warmup) / max(1, total - warmup)))
    return base_lr * (min_frac + (1.0 - min_frac) * 0.5 * (1.0 + math.cos(math.pi * prog)))

