class TokenOutputAdapter(nn.Module):
    """Hidden per position -> vocabulary scores per position."""

    def __init__(self, input_dim: int, vocab_size: int, substrate: "Substrate | None" = None):
        super().__init__()
        self.proj = default_substrate(substrate).linear(input_dim, vocab_size)

    def forward(self, h: Tensor) -> Tensor:
        return self.proj(h)


class FieldOutputAdapter(nn.Module):
    """Hidden per position -> target field value per position."""

    def __init__(self, input_dim: int, out_dim: int, substrate: "Substrate | None" = None):
        super().__init__()
        self.proj = default_substrate(substrate).linear(input_dim, out_dim)

    def forward(self, h: Tensor) -> Tensor:
        return self.proj(h)

