def linear(self, in_features: int, out_features: int, bias: bool = True) -> nn.Module:
    return nn.Linear(in_features, out_features, bias=bias)

def embedding(self, num_embeddings: int, embedding_dim: int) -> nn.Module:
    return nn.Embedding(num_embeddings, embedding_dim)

def scalar(self, shape: "int | Sequence[int]", init: float = 0.0, span: "float | None" = None) -> nn.Parameter:
    if isinstance(shape, int):
        shape = (shape,)
    return nn.Parameter(torch.full(tuple(int(s) for s in shape), float(init)))
